(259, 'booking_form', '<div class=\"wpbc_booking_form_structure wpbc_vertical\">\r\n  <div class=\"wpbc_structure_calendar\">\r\n    [calendar]\r\n  </div>\r\n  <div class=\"wpbc_structure_form\">\r\n     <div class=\"item-input_book\">[text name]<label>ФИО*</label></div>\r\n     <div class=\"item-input_book\">[email* email_field]<label>E-mail*</label></div>\r\n     <div class=\"item-input_book\">[text phone]<label>Телефон</label></div>\r\n     <div>[captcha]</div>\r\n     <p>[submit class:btn \"Отправить\"]</p>\r\n  </div>\r\n</div>\r\n<div class=\"wpbc_booking_form_footer\"></div>\r\n[lang=en_US]\r\n<div class=\"wpbc_booking_form_structure wpbc_vertical\">\r\n  <div class=\"wpbc_structure_calendar\">\r\n    [calendar]\r\n  </div>\r\n  <div class=\"wpbc_structure_form\">\r\n     <div class=\"item-input_book\">[text* name ]<label>Name*</label></div>\r\n     <div class=\"item-input_book\">[email* email_field]<label>E-mail*</label></div>\r\n     <div class=\"item-input_book\">[text phone ]<label>Phone</label></div>\r\n     <div>[captcha]</div>\r\n     <p>[submit class:btn \"Send\"]</p>\r\n  </div>\r\n</div>\r\n<div class=\"wpbc_booking_form_footer\"></div>', 'yes'),
(260, 'booking_form_show', '<div style=\"text-align:left;word-wrap: break-word;\">\r\n  <strong>Name</strong>: <span class=\"fieldvalue\">[name]</span><br/>\r\n  <strong>Email</strong>: <span class=\"fieldvalue\">[email_field]</span><br/>\r\n  <strong>Phone</strong>: <span class=\"fieldvalue\">[phone]</span><br/>\r\n</div>', 'yes'),
