(12253, 'wppb_roles_editor_capabilities', 'a:7:{s:7:\"general\";a:3:{s:5:\"label\";s:7:\"General\";s:4:\"icon\";s:19:\"dashicons-wordpress\";s:12:\"capabilities\";a:10:{i:0;s:14:\"edit_dashboard\";i:1;s:10:\"edit_files\";i:2;s:6:\"export\";i:3;s:6:\"import\";i:4;s:12:\"manage_links\";i:5;s:14:\"manage_options\";i:6;s:17:\"moderate_comments\";i:7;s:4:\"read\";i:8;s:15:\"unfiltered_html\";i:9;s:11:\"update_core\";}}s:10:\"post_types\";a:7:{s:4:\"post\";a:3:{s:5:\"label\";s:12:\"Записи\";s:4:\"icon\";s:20:\"dashicons-admin-post\";s:12:\"capabilities\";a:11:{i:0;s:10:\"edit_posts\";i:1;s:17:\"edit_others_posts\";i:2;s:13:\"publish_posts\";i:3;s:18:\"read_private_posts\";i:4;s:4:\"read\";i:5;s:12:\"delete_posts\";i:6;s:20:\"delete_private_posts\";i:7;s:22:\"delete_published_posts\";i:8;s:19:\"delete_others_posts\";i:9;s:18:\"edit_private_posts\";i:10;s:20:\"edit_published_posts\";}}s:4:\"page\";a:3:{s:5:\"label\";s:16:\"Страницы\";s:4:\"icon\";s:20:\"dashicons-admin-page\";s:12:\"capabilities\";a:11:{i:0;s:10:\"edit_pages\";i:1;s:17:\"edit_others_pages\";i:2;s:13:\"publish_pages\";i:3;s:18:\"read_private_pages\";i:4;s:4:\"read\";i:5;s:12:\"delete_pages\";i:6;s:20:\"delete_private_pages\";i:7;s:22:\"delete_published_pages\";i:8;s:19:\"delete_others_pages\";i:9;s:18:\"edit_private_pages\";i:10;s:20:\"edit_published_pages\";}}s:10:\"attachment\";a:3:{s:5:\"label\";s:20:\"Медиафайлы\";s:4:\"icon\";s:21:\"dashicons-admin-media\";s:12:\"capabilities\";a:2:{i:11;s:12:\"upload_files\";i:12;s:17:\"unfiltered_upload\";}}s:8:\"wp_block\";a:3:{s:5:\"label\";s:10:\"Блоки\";s:4:\"icon\";s:20:\"dashicons-admin-post\";s:12:\"capabilities\";a:6:{i:0;s:11:\"edit_blocks\";i:2;s:14:\"publish_blocks\";i:3;s:19:\"read_private_blocks\";i:5;s:13:\"delete_blocks\";i:6;s:21:\"delete_private_blocks\";i:9;s:19:\"edit_private_blocks\";}}s:15:\"acf-field-group\";a:3:{s:5:\"label\";s:12:\"Field Groups\";s:4:\"icon\";s:20:\"dashicons-admin-page\";s:12:\"capabilities\";a:1:{i:0;s:14:\"manage_options\";}