INSERT INTO `wp_a_postmeta` (`meta_id`, `post_id`, `meta_key`, `meta_value`) VALUES
(4417, 349, 'additional_information_banners_blok_1_descr', '<strong>Разрешено</strong>\r\n<ul>\r\n 	<li>проводить время в домашнем кругу</li>\r\n 	<li>готовить еду па плите и в духовке</li>\r\n 	<li>стирать вещи в стиральной машине</li>\r\n 	<li>курить на балконе при закрытой двери</li>\r\n 	<li>пользоваться интернетом и кабельным ТВ</li>\r\n</ul>\r\n<strong>Запрещено</strong>\r\n<ul>\r\n 	<li>устраивать вечеринки</li>\r\n 	<li>отмечать праздники</li>\r\n 	<li>курение в квартире</li>\r\n 	<li>мусорить в квартире</li>\r\n 	<li>шуметь в квартире</li>\r\n 	<li>небрежно относиться к имуществу в квартире</li>\r\n 	<li>присутствие большего количества людей, чем в договоре</li>\r\n</ul>'),
(4418, 349, '_additional_information_banners_blok_1_descr', 'field_5b17c552b33b4'),
(4419, 349, 'additional_information_banners_blok_1', ''),
(4420, 349, '_additional_information_banners_blok_1', 'field_5b17c480b33b1'),
(4421, 349, 'additional_information_banners_blok_2_title', 'Бесплатные услуги'),
(4422, 349, '_additional_information_banners_blok_2_title', 'field_5b17c573b33b6'),
(4423, 349, 'additional_information_banners_blok_2_img', '305'),
(4424, 349, '_additional_information_banners_blok_2_img', 'field_5b17c573b33b7'),
(4425, 349, 'additional_information_banners_blok_2_descr', '<p style=\"text-align: left;\"><strong>Постельное бельё</strong>\r\nБесплатно мы предоставляем по одному комплекту белья на каждую\r\nкровать и одно полотенце на человека. Стоимость использования каждого\r\nдополнительного комплекта белья 200 руб и полотенца 100 руб.\r\n<strong>Коллекция фильмов</strong>\r\nВ каждой квартире есть флэшка с бесплатными фильмами, на которой около 20 интересных кино разных жанров. Залог за флешку 700 руб, он возвращается вам при выезде.\r\n<strong>Беспроводной интернет и кабельное телевидение</strong>\r\nВ каждой квартире есть памятка с паролем от Wi-Fi.</p>'),
(4426, 349, '_additional_information_banners_blok_2_descr', 'field_5b17c573b33b8'),
(4427, 349, 'additional_information_banners_blok_2', ''),
(4428, 349, '_additional_information_banners_blok_2', 'field_5b17c573b33b5'),
(4429, 349, 'additional_information_banners_blok_3_title', 'Платные услуги'),
