INSERT INTO `wp_a_postmeta` (`meta_id`, `post_id`, `meta_key`, `meta_value`) VALUES
(8078, 662, 'additional_information_banners_blok_3_descr', '<strong>Аренда игровой приставки</strong>\r\nАренда приставки X-box 360 или Sony Play Station с установленными\r\nиграми и двумя джойстиками. Стоимость проката 1000 руб за первые\r\nсутки и всего 100 руб за каждые последующие.\r\n<strong>Комплект нового постельного белья</strong>\r\nДля вас мы можем купить новый комплект постельного белья из IKEA размером 2 м * 2 м. Бельё дествительно будет новое, в упаковке.Стоимость такой услуги всего 500 руб на весь срок проживания.Например, если вы планируете жить две недели, то получаетсявсего по 35 руб в день.'),
(8079, 662, '_additional_information_banners_blok_3_descr', 'field_5b17c583b33bc'),
(8080, 662, 'additional_information_banners_blok_3', ''),
(8081, 662, '_additional_information_banners_blok_3', 'field_5b17c583b33b9'),
