(12097, 819, 'included_in_cost_0_title', 'проживание по количеству спальных мест'),
(12098, 819, 'included_in_cost_1_title', 'чистое постельное бельё и полотенца'),
(12099, 819, 'included_in_cost_2_title', 'беспроводной интернет'),
