(12731, 824, 'image_equipment', '680'),
(12732, 824, 'included_in_cost_0_title', 'проживание по количеству спальных мест'),
(12733, 824, 'included_in_cost_1_title', 'чистое постельное бельё и полотенца'),
(12734, 824, 'included_in_cost_2_title', 'беспроводной интернет'),
