(13366, 829, 'image_equipment', '629'),
(13367, 829, 'included_in_cost_0_title', 'проживание по количеству спальных мест'),
(13368, 829, 'included_in_cost_1_title', 'чистое постельное бельё и полотенца'),
(13369, 829, 'included_in_cost_2_title', 'беспроводной интернет'),
