(14635, 839, 'image_equipment', '497'),
(14636, 839, 'included_in_cost_0_title', 'проживание по количеству спальных мест'),
(14637, 839, 'included_in_cost_1_title', 'чистое постельное бельё и полотенца'),
(14638, 839, 'included_in_cost_2_title', 'беспроводной интернет'),
